function sound(type,id=world.selected,withHaptic=true){if(type==='angry')haptic('bite',[30,45,55],.8);if(type==='toy')haptic('toy',[10,35,10],.35);if(type==='land')haptic('land',12,.3);if(type==='scoop'&&withHaptic)haptic('scoop',8,.07);if(type==='thump')haptic('wolf',[20,25,30],.1);if(type==='swat')haptic('swat',[24,20,38],.55);if(!music||audioPaused||!audio||audio.state!=='running')return;if(type==='purr'){if(elapsed-lastPurr<.5)return;lastPurr=elapsed;}if(type==='thunder')thunderSound();if(type==='plane'){tone(88,8,'triangle',.018,0,68);tone(132,8,'sine',.011,0,96);}if(type==='howl'){tone(320,1.4,'triangle',.065,0,510);tone(510,1.2,'sine',.055,.3,390);tone(390,.75,'sine',.045,1.2,560);}if(type==='bark'){tone(310,.16,'square',.055,0,190);tone(360,.18,'square',.05,.23,205);}if(type==='roar'){tone(105,1.2,'sawtooth',.075,0,62);tone(155,1.05,'triangle',.055,.12,82);}if(type==='mouse-flee'){tone(1250,.1,'square',.065,0,2200);tone(1700,.08,'triangle',.05,.11,2450);}if(type==='critter-hit'){tone(340,.06,'square',.055,0,120);tone(980,.08,'triangle',.035,.04,1500);}if(type==='gecko-call'){tone(2250,.055,'square',.035,0,1780);tone(2050,.06,'triangle',.03,.09,1540);}if(type==='gecko-scurry')tone(520,.045,'triangle',.018,0,760);if(type==='squeak'){tone(900,.13,'triangle',.078,0,1720);tone(1290,.1,'square',.045,.03,2050);tone(1020,.13,'triangle',.072,.2,1800);tone(1430,.09,'square',.04,.23,2160);}if(type==='drink'){tone(430,.09,'sine',.038,0,260);tone(570,.07,'triangle',.032,.13,330);tone(390,.1,'sine',.03,.28,230);}if(type==='dog-love'){tone(620,.12,'sine',.022);tone(820,.18,'sine',.018,.12);}if(type==='swat'){tone(115,.15,'square',.12,0,42);tone(720,.055,'triangle',.085,0,180);tone(1480,.04,'square',.045,.045,390);}if(type==='scoop'){for(let i=0;i<14;i++)tone(700+Math.random()*1800,.055,'triangle',.045,i*.045,180);}if(type==='thump')tone(150,.18,'triangle',.11,0,45);if(type==='jump')tone(220,.13,'sine',.027,0,440);if(type==='chirp'){tone(1900,.12,'sine',.021,0,2700);tone(2500,.08,'sine',.016,.15,2100);}if(type==='land')tone(95,.09,'sine',.026,0,55);if(type==='meow'){meowVoice(id);}if(type==='purr'){for(let i=0;i<7;i++){tone(86+i%2*12,.13,'triangle',.1,i*.09,72);tone(170,.12,'sine',.036,i*.09,145);}}if(type==='eat'){tone(190,.045,'triangle',.02,0,90);tone(260,.05,'triangle',.015,.06,110);}if(type==='toy'){tone(1800,.06,'sine',.025);tone(2300,.08,'sine',.016,.07);}if(type==='coin'){const delay=Math.max(0,lastCoinDingTime-audio.currentTime);tone(880,.12,'sine',.026,delay);tone(1320,.2,'sine',.018,delay+.1);lastCoinDingTime=audio.currentTime+delay+.18;}if(type==='angry'){tone(155,.3,'sawtooth',.018,0,80);}}
function meowVoice(id){
 if(!music||audioPaused||document.hidden||!audio||audio.state!=='running')return;
 const f=id==='hoya'?610:420,d=id==='hoya'?.58:.82;
 if(!audio.createBiquadFilter){tone(f,d,'triangle',.06,0,f*.65);return;}
 const t=audio.currentTime,o=audio.createOscillator(),gain=audio.createGain();o.type='sawtooth';o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(f*1.35,t+.13);o.frequency.exponentialRampToValueAtTime(f*.65,t+d);
 gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(.085,t+.07);gain.gain.exponentialRampToValueAtTime(.055,t+d*.55);gain.gain.exponentialRampToValueAtTime(.0001,t+d);gain.connect(audio.destination);
 const filters=[audio.createBiquadFilter(),audio.createBiquadFilter()];filters.forEach((filter,i)=>{filter.type='bandpass';filter.Q.value=i?5:3;filter.frequency.setValueAtTime(i?2600:1150,t);filter.frequency.exponentialRampToValueAtTime(i?1300:520,t+d*.85);o.connect(filter);filter.connect(gain);});
 voices.add(o);o.start(t);o.stop(t+d+.03);o.onended=()=>{voices.delete(o);o.disconnect();filters.forEach(filter=>filter.disconnect());gain.disconnect();};
}
function audioTick(dt){if(bgmMedia||!music||!started||!audio||audio.state!=='running')return;bgmClock-=dt;if(bgmClock<=0){bgmClock=.6;const notes=[261.63,329.63,392,493.88,440,392,329.63,293.66,246.94,293.66,392,440,392,329.63,293.66,0];const section=Math.floor(bgmStep/16)%8,transpose=[1,1.12246,.8909,1,1.2599,1.12246,.8909,1][section];const index=section%2?15-bgmStep%16:bgmStep%16;const f=notes[index]*transpose;if(f)tone(f,.95,'sine',.018);if(bgmStep%4===0){tone(bgmStep%16<8?130.81:146.83,2.1,'sine',.02);tone(bgmStep%16<8?196:220,1.8,'sine',.01,.1);}bgmStep=(bgmStep+1)%128;}}
function screenPoint(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*view.width/r.width,y:(e.clientY-r.top)*view.height/r.height};}
function toWorld(p){return {x:(p.x-view.cx)/zoom+focus.x,y:(p.y-view.cy)/zoom+focus.y};}
function sensitive(c,p){const x=p.x-c.x,y=p.y-c.y,tail=x>=13&&x<=25&&y>=-25&&y<=-7,lowerBelly=Math.abs(x)<=8&&y>=-3&&y<=4;return tail||lowerBelly;}
function hit(c,p){const feet=c.y-(c.z||0)-(c.lift||0);return Math.abs(p.x-c.x)<22&&p.y>feet-44&&p.y<feet+8;}
canvas.addEventListener('pointerdown',e=>{if(!started||drag||pointerId!==null)return;unlock().then(flushAmbientSound);pointerId=e.pointerId;canvas.setPointerCapture(e.pointerId);const p=screenPoint(e),q=toWorld(p);if(world.storm?.thunderStarted&&!world.storm.curtainClosed&&q.x>=8&&q.x<=127&&q.y>=18&&q.y<=156){world.closeStormCurtain();save();hud();return;}if(world.critter?.kind==='food-mouse'&&world.hitCritter(q.x,q.y))return;if(world.storm?.thunderStarted&&!world.storm.curtainClosed&&world.paintingAt(q.x,q.y)){openPaintingPanel();return;}if(world.storm?.thunderStarted&&!world.storm.curtainClosed)return;if(world.resetObject(q.x,q.y)){save();hud();return;}if(world.hitMosquito(q.x,q.y))return;if(world.hitCritter(q.x,q.y))return;if(world.hitGecko(q.x,q.y))return;if(!world.interacting&&!world.cats.some(c=>hit(c,q))&&Math.abs(q.x-world.fountain.x)<22&&q.y>=world.fountain.y-40&&q.y<=world.fountain.y+6){world.refillWater();save();hud();return;}if(!world.interacting&&Math.hypot(q.x-world.yarn.x,q.y-world.yarn.y)<13){world.playYarn();return;}const flowerNote=!world.cats.some(c=>hit(c,q))&&wonders.inspect(world,q.x,q.y);if(flowerNote){notify(flowerNote,6);return;}if(world.paintingAt(q.x,q.y)){openPaintingPanel();return;}if(world.wolf){world.hitWolf(q.x,q.y);return;}if(world.close){const c=world.cats.find(c=>c.id===world.close);if(sensitive(c,toWorld(p)))world.rejectPet('不喜歡尾巴或下腹被碰','sensitive');stroke={...p,time:e.timeStamp};}else if(zoom<1.1){const target=[...world.cats].sort((a,b)=>b.y-a.y).find(c=>hit(c,toWorld(p)));if(target)world.touchCat(target.id);}});
canvas.addEventListener('pointermove',e=>{if(e.pointerId!==pointerId||!stroke||!world.close)return;const p=screenPoint(e),c=world.cats.find(c=>c.id===world.close),distance=Math.hypot(p.x-stroke.x,p.y-stroke.y),dt=Math.max(.008,(e.timeStamp-stroke.time)/1000);if(sensitive(c,toWorld(p))){world.rejectPet('不喜歡尾巴或下腹被碰','sensitive');}else if(hit(c,toWorld(p))&&hit(c,toWorld(stroke))){if(world.pet(distance,distance/dt))particles.push({x:p.x,y:p.y,life:1.4,kind:'heart'});if(c.state==='pet-happy'&&distance>0)haptic('pet',8,.22);}stroke={...p,time:e.timeStamp};});
function stopStroke(e){if(e.pointerId!==pointerId)return;stroke=null;pointerId=null;try{navigator.vibrate?.(0);}catch{}}
for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,stopStroke);
function dragStart(e,type){if(!started||world.interacting||drag||pointerId!==null)return;e.preventDefault();unlock();const source=e.currentTarget;source.setPointerCapture(e.pointerId);drag={type,id:e.pointerId,source,...screenPoint(e),inside:false};notify(type==='scoop'?'把鏟子拖到右下角貓砂盆。':type==='food'?'把小碗拖到房間地板上。':'移動羽毛，選中的貓會持續追著玩。');hud();}
function offsetTool(p,type){return type==='food'?p:{x:p.x-22,y:p.y+18};}
 for(const type of ['food','toy','scoop']){const source=$(type);source.addEventListener('pointerdown',e=>dragStart(e,type));source.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;if(world.interacting){drag=null;world.toy=null;return;}e.preventDefault();const pointer=screenPoint(e),shown=offsetTool(pointer,type),p=toWorld(shown);Object.assign(drag,shown,{inside:p.x>=world.floorBounds.left&&p.x<=world.floorBounds.right&&p.y>=205&&p.y<=world.floorBounds.bottom});if(type==='toy'){if(drag.lastToyPoint&&Math.hypot(p.x-drag.lastToyPoint.x,p.y-drag.lastToyPoint.y)>2)drag.toyMovingUntil=world.time+.35;drag.lastToyPoint=p;world.toy=world.toyAt(p.x,p.y);if(world.toy)world.toy.movingUntil=drag.toyMovingUntil||-1;drag.inside=!!world.toy;if(world.toy&&elapsed-lastBell>.35){lastBell=elapsed;sound('toy');}}else if(type==='scoop'){const over=p.x>=world.litter.x-23&&p.x<=world.litter.x+25&&p.y>=world.litter.y-17&&p.y<=world.litter.y+21;drag.inside=over;if(over&&!drag.attempted){drag.attempted=true;drag.session=world.beginLitterCleaning();}if(over&&drag.session){if(drag.lastWorld){drag.distance=(drag.distance||0)+Math.hypot(p.x-drag.lastWorld.x,p.y-drag.lastWorld.y);while(drag.distance>=15&&drag.session.progress<drag.session.required){drag.distance-=15;world.scoopLitter(drag.session);}}drag.lastWorld=p;}else drag.lastWorld=null;}});source.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.id)return;const shown=offsetTool(screenPoint(e),type),p=toWorld(shown);if(type==='food'){if(world.dropFood(p.x,p.y))sound('toy');else if(world.foods.length>=2)notify('房間最多放兩盤。');else notify('放在地毯附近的地板上就可以了。');}else if(type==='scoop'&&drag.session&&drag.session.progress<drag.session.required)notify(`再擦 ${drag.session.required-drag.session.progress} 下就乾淨了。`);world.toy=null;drag=null;save();hud();});for(const event of ['pointercancel','lostpointercapture'])source.addEventListener(event,()=>{if(drag?.source===source){drag=null;world.toy=null;hud();}});}
function closeRewardPanel(){const panel=$('reward-panel');panel.hidden=true;$('reward-open').setAttribute('aria-expanded','false');}
$('reward-open').onclick=()=>{if(!started||world.rewardFood)return;closePaintingPanel();const panel=$('reward-panel'),open=panel.hidden;panel.hidden=!open;$('reward-open').setAttribute('aria-expanded',String(open));};
