function closePaintingPanel(){$('painting-panel').hidden=true;}
function renderPaintingPanel(){const host=$('painting-panel').querySelector('div'),nodes=[];paintingNames.forEach((name,index)=>{if(index===0||index===6){const title=document.createElement('strong');title.textContent=index===0?'世界名畫':'角色與貓咪';nodes.push(title);}const button=document.createElement('button'),thumb=paintingThumbnail(index),text=document.createElement('span'),price=document.createElement('small');button.type='button';button.dataset.painting=String(index);text.textContent=name;price.textContent=`${PAINTING_PRICE} Coins`;text.appendChild(price);button.append(thumb,text);button.setAttribute('aria-current',String(index===world.paintingIndex));button.disabled=index!==world.paintingIndex&&world.coins<PAINTING_PRICE;button.onclick=()=>{if(world.selectPainting(index)){save();closePaintingPanel();}hud();};nodes.push(button);});host.replaceChildren(...nodes);}
