 source.addEventListener('pointerdown',e=>{const kind=source.dataset.reward,item=REWARD_FOODS[kind];if(!started||world.rewardFood||drag||pointerId!==null)return;if(world.coins<item.price){notify(`金幣不足，${item.name}需要 ${item.price} Coins。`);return;}e.preventDefault();unlock();source.setPointerCapture(e.pointerId);drag={type:'reward',kind,id:e.pointerId,source,...screenPoint(e),inside:false};source.setAttribute('aria-pressed','true');notify(`把${item.name}拖到房間空曠的地板。`);hud();});
 source.addEventListener('pointermove',e=>{if(drag?.type!=='reward'||drag.source!==source||e.pointerId!==drag.id)return;e.preventDefault();const shown=screenPoint(e),p=toWorld(shown);Object.assign(drag,shown,{inside:world.validFloorDrop(p.x,p.y)});hud();});
 source.addEventListener('pointerup',e=>{if(drag?.type!=='reward'||drag.source!==source||e.pointerId!==drag.id)return;const shown=screenPoint(e),p=toWorld(shown),placed=drag.inside&&world.placeRewardFood(drag.kind,p.x,p.y);source.setAttribute('aria-pressed','false');drag=null;if(placed){closeRewardPanel();syncAudioToGameState();save();}else notify('請放在空曠地板；取消或無效位置不會扣 Coins。');hud();});
