function frame(t){const rawDt=last?Math.max(0,(t-last)/1000):0,dt=Math.min(.05,rawDt);last=t;if(!document.hidden){elapsed+=rawDt;const threatBefore=world.wolf;if(started)world.update(dt,new Date().getHours(),rawDt);else world.outdoorNight=new Date().getHours()>=18||new Date().getHours()<6;if(world.wolf!==threatBefore)threatAudioPermission=world.wolf||null;if(!world.wolf)threatAudioPermission=null;syncAudioToGameState();syncMosquitoBuzz();flushAmbientSound();audioTick(dt);for(const event of world.events.splice(0)){if(event.type==='squeak'||event.type==='gecko-call'||event.type==='scoop')ambientSound(event.type,event.id);else sound(event.type,event.id);if(event.text)notify(event.text,event.type==='dream'?7.2:3.5);if(event.type==='stat-feedback'){showStatFeedback(event);hud();}if(event.type==='coin'&&event.amount){showCoinGain(event.amount);particles.push({x:200,y:40,life:1.4,kind:'coin'});save();hud();}if(event.type==='reward-heart'){const c=world.cats.find(cat=>cat.id===event.id),feet=c?c.y-(c.z||0)-(c.lift||0):250;particles.push({x:(c.x-focus.x)*zoom+view.cx+(Math.random()-.5)*14,y:(feet-35-focus.y)*zoom+view.cy,life:1.4,kind:'heart'});}if(event.type==='dog-love')particles.push({x:79+(Math.random()-.5)*10,y:98,life:1.4,kind:'heart'});if(event.type==='clean-mess'){const at={plant:[8,184],curtain:[70,90],catTree:[28,258],lamp:[205,140],litter:[238,294],water:[35,294]}[event.id]||[120,250];for(let i=0;i<4;i++)particles.push({x:at[0]+(i-1.5)*5,y:at[1]+i%2*4,life:1+i*.12,kind:'coin'});save();hud();}}render(dt);if(elapsed>noteUntil)$('note').classList.remove('visible');if(elapsed-lastHud>.2){hud();lastHud=elapsed;}if(started&&elapsed-lastSave>5){save();lastSave=elapsed;}}else stopMosquitoBuzz();requestAnimationFrame(frame);}
